// Seoul National University Gwanak campus (서울대학교 관악캠퍼스, 서울 관악구). Data is generated by scripts/campuses/snu/build-package.mjs
// from the pilot (pilot/snu-gwanak-v2): every destructible building of active-models.json (the detailed symbol buildings + the generic
// v2 ones; the lists live in data.js, not here), the hospitals (86동 치과병원·85-1동 동물병원, user decision 2026-10-20) as protected
// models with the shield, a baked ground with the pilot's ground shader (the SKKU port src/campuses/skku/ground-look.js; the pilot's
// final-materials.js is the same shader as dankook's), the landscape (자하연 pond: a plain transparent water sheet as in the preview,
// so no water shader; 아크로폴리스 flights / plaza) and the non-destructible context (관악산·대학동·낙성대·봉천동) fading into the haze.
// Local only until the user approves (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, SNU_PLACEMENTS, SNU_DETAILED_IDS, SNU_BUILDING_BASE, SNU_HEIGHT_GRIDS, SNU_HEIGHT_RANGE_M, SNU_ENV_IDS, SNU_ENV_MANIFEST_IDS, SNU_LOOK, SNU_ZONES, SNU_DISPLAY, SNU_PROVENANCE } from './data.js';
import { SNU_FOOTPRINTS } from './footprints.js';
import { SNU_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(SNU_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/snu/${file}`, import.meta.url).href;
const HAZE = SNU_DISPLAY.haze || '#dde5e8', FADE = SNU_DISPLAY.fade;
const START_ID = MODEL_IDS.includes('admin') ? 'admin' : MODEL_IDS[0];

export const SNU = Object.freeze({
  id: 'snu',
  meta: Object.freeze({ school: '서울대학교', campus: '관악캠퍼스', short: '서울대', modelNoun: '서울대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: SNU_PLACEMENTS,
  approvedCount: SNU_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: SNU_DETAILED_IDS,
  startBuildingId: START_ID,
  // Start (proposal, the main session adjusts it on screen): from the north-west over the 잔디광장 toward 행정관 (60동) with the
  // 아크로폴리스, 중앙도서관 (62동), 학생회관 (63동) and the 관정관 (62-1동) gold box behind. Box = 학생회관 (E -185) .. 관정관 (E -25),
  // 행정관 (N -79) .. 관정관 (N -196). World units (metres x 0.5, z = -N); azimuth -2.55 = camera to the north-west of the box.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-105, -3, 32]), max: Object.freeze([-6, 14, 108]), azimuth: -2.55 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: SNU_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: SNU_HEIGHT_GRIDS, buildingBase: SNU_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, 관악산 canopy lowered by an estimate, 자하연 basin + floor / photo level evidence, pilot/snu-gwanak-v2); not a survey' }),
  environment: Object.freeze({ provenance: SNU_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the landscape estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: SNU_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(SNU_LOOK, SNU_ZONES),
      fade: Object.freeze({ centre_m: Object.freeze(FADE ? [...FADE.centreEN] : [70, -8]), near_m: FADE?.r0_m ?? 1350, far_m: FADE?.r1_m ?? 2400, ...(FADE?.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/snu-gwanak-v2 preview ground + landscape + context, baked' }),
  }),
  // Hospitals (86동 치과병원·85-1동 동물병원): never destructible; weapons meet the protective shield (src/protected-buildings.js), own small cache.
  protected: Object.freeze({
    manifestURL: asset('protected/manifest.json'),
    models: SNU_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the hospitals or the context.
  hazardTape: Object.freeze({ footprints: SNU_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 900, far: 3000 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-170, 150, 60]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: SNU_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default SNU;
